        if fitz is None:
            raise RuntimeError("PyMuPDF (fitz) не установлен. Невозможно использовать экспериментальный текстовый слой.")

        logger.info(f"TextLayerPdfProcessor: обработка файла {source_name or 'без имени'}")
        doc = fitz.open(stream=pdf_bytes, filetype="pdf")
        try:
            page = doc[0]
            lines = self._extract_lines(page)
            selected_blocks = self._build_blocks(lines, page.rect.width, page.rect.height)

            block_texts = []
            block_data = {}

            for idx, block in enumerate(selected_blocks, start=1):
                text = block["text"].strip()
                if text:
                    block_texts.append(text)
                    block_data[f"block_{idx}"] = {
                        "bbox": block["bbox"],
                        "score": block.get("score", 0),
                        "text": text,
                    }
                    self._store_block_text(text, source_name)

            full_text = "\n\n".join(block_texts)
            return {
                "text": full_text,
                "blocks": block_texts,
                "blocks_data": block_data,
            }
        finally:
            doc.close()

