            m = cls.ITEM_RE.match(t)
            rest = m.group(2)
            if cls._has_strong_word(t) or len(rest) >= 18:
                return "item"
        if cls.DASH_RE.match(t):
            return "dash"
        return "continuation"

    @classmethod
    def _trim_words_to_embedded_requirement(cls, ws):
        if not ws:
            return ws
        for idx in range(len(ws)):
            token = cls._normalize_text(ws[idx][4])
            token_clean = token.strip().replace(".", "").replace(")", "")
            if not re.match(r"^\d{1,2}\*?$", token_clean):
                continue
            rest_text = cls._normalize_text(" ".join(str(w[4]) for w in ws[idx:]))
            if cls._is_short_dimension_item(rest_text):
                continue
            if cls._has_strong_word(rest_text) or len(rest_text) >= 28:
                return ws[idx:]
        return ws

    def _extract_lines(self, page):
        words = page.get_text("words", sort=True)
        groups = {}

        for w in words:
            if len(w) < 8:
                continue
            x0, y0, x1, y1, text, block_no, line_no, _ = w[:8]
            text = self._normalize_text(text)
            if not text:
                continue
            key = (int(block_no), int(line_no))
            groups.setdefault(key, []).append(w)

        lines = []
        for ws in groups.values():
            ws = sorted(ws, key=lambda z: z[0])
            ws = self._trim_words_to_embedded_requirement(ws)
            text = self._normalize_text(" ".join(str(w[4]) for w in ws))
            if not text:
                continue
            bbox = [
                min(w[0] for w in ws),
                min(w[1] for w in ws),
                max(w[2] for w in ws),
                max(w[3] for w in ws),
            ]
            lines.append({
                "text": text,
                "bbox": bbox,
                "x1": bbox[0],
                "y1": bbox[1],
                "x2": bbox[2],
                "y2": bbox[3],
                "kind": self._classify_line(text),
                "item_number": self._item_number(text),
            })

        lines.sort(key=lambda line: (line["y1"], line["x1"]))
        return lines

    @staticmethod
    def _median_line_height(lines):
        hs = sorted(l["bbox"][3] - l["bbox"][1] for l in lines if l["bbox"][3] > l["bbox"][1])
        if not hs:
            return 8.0
        return hs[len(hs) // 2]

    @staticmethod
    def _same_requirement_zone(line, block_bbox, base_x, page_w):
        b = line["bbox"]
        if abs(line["x1"] - base_x) <= 35:
            return True
        if base_x <= line["x1"] <= base_x + page_w * 0.22:
            return True
        if TextLayerPdfProcessor._overlap_x(b, block_bbox) >= 0.25:
            return True
        return False

    def _build_candidate_from_anchor(self, lines, anchor_index, page_w, page_h):
        anchor = lines[anchor_index]
        if anchor["kind"] != "item":
            return None

        base_x = anchor["x1"]
        collected = [anchor]
        block_bbox = anchor["bbox"][:]
        med_h = self._median_line_height(lines)
        last_y2 = anchor["y2"]

        for j in range(anchor_index + 1, len(lines)):
            line = lines[j]
            if line["y1"] < anchor["y1"] - 1:
                continue
            gap = line["y1"] - last_y2
            if gap > max(18.0, med_h * 3.2):
                if line["kind"] != "item" or not self._same_requirement_zone(line, block_bbox, base_x, page_w):
                    break
            if line["kind"] in ("signature", "title"):
                if len(collected) >= 1:
                    break
                continue
            if line["kind"] == "bad_dim":
                continue
            if line["kind"] == "item":
                if not self._same_requirement_zone(line, block_bbox, base_x, page_w):
                    continue
                collected.append(line)
                block_bbox = self._bbox_union(collected)
                last_y2 = max(last_y2, line["y2"])
                continue
            if line["kind"] in ("dash", "continuation"):
                if self._same_requirement_zone(line, block_bbox, base_x, page_w):
                    if line["kind"] == "dash" or len(line["text"]) >= 5:
                        collected.append(line)
                        block_bbox = self._bbox_union(collected)
                        last_y2 = max(last_y2, line["y2"])
                continue

        if not collected:
            return None

        text = "\n".join(line["text"] for line in collected)
        nums = [line["item_number"] for line in collected if line.get("item_number") is not None]
        return {
            "lines": collected,
            "bbox": self._bbox_union(collected),
            "text": text,
            "item_numbers": nums,
            "line_count": len(collected),
        }

    def _score_candidate(self, candidate, page_w, page_h):
        text = candidate["text"]
        u = self._upper(text)
        bbox = candidate["bbox"]
        item_count = len(candidate["item_numbers"])
        dash_count = sum(1 for line in candidate["lines"] if line["kind"] == "dash")
        cont_count = sum(1 for line in candidate["lines"] if line["kind"] == "continuation")
        strong_count = sum(1 for word in self.STRONG_WORDS if word in u)

        bw = bbox[2] - bbox[0]
        bh = bbox[3] - bbox[1]
        area_rel = (bw * bh) / max(1.0, page_w * page_h)

        score = 0.0
        reasons = []
        if item_count >= 1:
            score += 30
            reasons.append("+items")
        if item_count >= 2:
            score += 35
            reasons.append("+multi_items")
        if dash_count > 0:
            score += 12
            reasons.append("+dash_subitems")
        if cont_count > 0:
            score += 8
            reasons.append("+continuations")
        if strong_count:
            score += min(50, strong_count * 8)
            reasons.append("+keywords")

        nums = candidate["item_numbers"]
        if nums:
            uniq = []
            for n in nums:
                if n not in uniq:
                    uniq.append(n)
            if len(uniq) >= 2:
                seq_bonus = 0
                for a, b in zip(uniq, uniq[1:]):
                    if b == a + 1:
                        seq_bonus += 8
                if seq_bonus:
                    score += seq_bonus
                    reasons.append("+sequence")
            if 1 in uniq:
                score += 8
                reasons.append("+has_1")

        if area_rel > 0.20:
            score -= 60
            reasons.append("-huge")
        if bw > page_w * 0.75:
            score -= 45
            reasons.append("-too_wide")
        if bh > page_h * 0.45:
            score -= 35
            reasons.append("-too_tall")
        if item_count == 1 and len(text) < 45 and dash_count == 0:
            score -= 45
            reasons.append("-short_single")
        if any(self._is_signature(line["text"]) or self._is_title_block(line["text"]) for line in candidate["lines"]):
            score -= 100
            reasons.append("-signature_or_title")

        candidate["score"] = round(score, 2)
        candidate["reasons"] = reasons
        candidate["features"] = {
            "item_count": item_count,
            "dash_count": dash_count,
            "continuation_count": cont_count,
            "strong_word_count": strong_count,
            "area_rel": round(area_rel, 5),
        }
        return candidate

    def _make_candidates(self, lines, page_w, page_h):
        candidates = []
        for i, line in enumerate(lines):
            if line["kind"] != "item":
                continue
            candidate = self._build_candidate_from_anchor(lines, i, page_w, page_h)
            if not candidate:
                continue
            candidate = self._score_candidate(candidate, page_w, page_h)
            if candidate["score"] < 15:
                continue
            candidates.append(candidate)

        candidates.sort(key=lambda c: c["score"], reverse=True)
        unique = []
        for c in candidates:
            duplicate = False
            for old in unique:
                if self._rect_iou(c["bbox"], old["bbox"]) > 0.55:
                    duplicate = True
                    break
                cx1, cy1, cx2, cy2 = c["bbox"]
                ox1, oy1, ox2, oy2 = old["bbox"]
                inside = (
                    cx1 >= ox1 - 5 and cy1 >= oy1 - 5 and
                    cx2 <= ox2 + 5 and cy2 <= oy2 + 5
                )
                if inside:
                    duplicate = True
                    break
            if not duplicate:
                unique.append(c)
        return unique

    @staticmethod
    def _select_blocks(candidates, max_blocks=3):
        selected = []
        for candidate in sorted(candidates, key=lambda c: c["score"], reverse=True):
            if candidate["score"] < 35:
                continue
            bb = candidate["bbox"]
            overlap = False
            for old in selected:
                if TextLayerPdfProcessor._rect_iou(bb, old["bbox"]) > 0.25:
                    overlap = True
                    break
            if overlap:
                continue
            selected.append(candidate)
            if len(selected) >= max_blocks:
                break
        return selected

