class TokenStorage:
    """Хранилище уникальных токенов текста для последующего обучения."""

    def __init__(self, db_path="results/unique_tokens.db"):
        self.db_path = db_path
        os.makedirs(os.path.dirname(db_path) or ".", exist_ok=True)
        self._init_db()

    def _connect(self):
        conn = sqlite3.connect(self.db_path)
        conn.row_factory = sqlite3.Row
        return conn

    def _init_db(self):
        with self._connect() as conn:
            conn.execute(
                """
                CREATE TABLE IF NOT EXISTS unique_tokens (
                    token TEXT PRIMARY KEY,
                    first_seen_at TEXT NOT NULL,
                    last_seen_at TEXT NOT NULL,
                    source_file TEXT,
                    seen_count INTEGER NOT NULL DEFAULT 1
                )
                """
            )
            conn.execute(
                """
                CREATE TABLE IF NOT EXISTS processed_blocks (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    source_file TEXT,
                    block_hash TEXT UNIQUE,
                    block_text TEXT NOT NULL,
                    created_at TEXT NOT NULL
                )
                """
            )
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_unique_tokens_seen_count ON unique_tokens(seen_count)"
            )
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_processed_blocks_source_file ON processed_blocks(source_file)"
            )

    @staticmethod
    def _normalize_token(token):
        if token is None:
            return ""
        return str(token).replace("\xa0", " ").strip()

    @staticmethod
    def _tokenize_block_text(text):
        if text is None:
            return []
        normalized = str(text).replace("\xa0", " ")
        return [tok for tok in normalized.split() if tok.strip()]

    def store_block_tokens(self, block_text, source_file=""):
        if not block_text or not str(block_text).strip():
            return 0

        tokens = self._tokenize_block_text(block_text)
        if not tokens:
            return 0

        block_hash = self._hash_block(block_text)
        now = datetime.utcnow().isoformat(timespec="seconds")

        with self._connect() as conn:
            conn.execute(
                """
                INSERT OR IGNORE INTO processed_blocks (source_file, block_hash, block_text, created_at)
                VALUES (?, ?, ?, ?)
                """,
                (source_file, block_hash, str(block_text), now),
            )

            for raw_token in tokens:
                clean = self._normalize_token(raw_token)
                if not clean:
                    continue
                conn.execute(
                    """
                    INSERT INTO unique_tokens (token, first_seen_at, last_seen_at, source_file, seen_count)
                    VALUES (?, ?, ?, ?, 1)
                    ON CONFLICT(token) DO UPDATE SET
                        last_seen_at = excluded.last_seen_at,
                        source_file = excluded.source_file,
                        seen_count = unique_tokens.seen_count + 1
                    """,
                    (clean, now, now, source_file),
                )

        return len(set(tokens))

    @staticmethod
    def _hash_block(block_text):
        text = "" if block_text is None else str(block_text)
        return str(abs(hash(text.strip())))

    def get_unique_tokens(self):
        with self._connect() as conn:
            rows = conn.execute("SELECT token FROM unique_tokens ORDER BY token").fetchall()
            return [row["token"] for row in rows]

    def get_token_stats(self):
        with self._connect() as conn:
            rows = conn.execute(
                "SELECT token, seen_count, source_file, last_seen_at FROM unique_tokens ORDER BY token"
            ).fetchall()
            return [dict(row) for row in rows]


class BasePdfProcessor(ABC):
    def __init__(self, token_storage=None):
        self.token_storage = token_storage

    @classmethod
    @abstractmethod
    def supports(cls, file_name):
        raise NotImplementedError

    @abstractmethod
    def process(self, pdf_bytes, source_name=""):
        raise NotImplementedError

    def _store_block_text(self, block_text, source_name=""):
        if self.token_storage is not None:
            self.token_storage.store_block_tokens(block_text, source_name)


class OCRPdfProcessor(BasePdfProcessor):
    """OCR-процессор для .dwg.pdf"""

    @classmethod
    def supports(cls, file_name):
        name = str(file_name or "").lower()
        return ".dwg.pdf" in name or name.endswith(".dwg.pdf")

    def process(self, pdf_bytes, source_name=""):
        if cv2 is None or np is None or pytesseract is None or convert_from_bytes is None:
            raise RuntimeError("Для OCR требуется cv2 / numpy / pytesseract / pdf2image")

        logger.info(f"OCRPdfProcessor: обработка файла {source_name or 'без имени'}")
        pages = convert_from_bytes(pdf_bytes, dpi=300)
        if not pages:
            raise RuntimeError("Не удалось конвертировать PDF в изображения")

        image = np.array(pages[0])
        gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
        gray = cv2.GaussianBlur(gray, (3, 3), 0)
        _, binary = cv2.threshold(gray, 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU)
        custom_config = r"--psm 6 -c preserve_interword_spaces=1"
        text = pytesseract.image_to_string(binary, lang="rus", config=custom_config).strip()
        cleaned = self._clean_ocr_text(text)
        if cleaned:
            self._store_block_text(cleaned, source_name)
        return {
            "text": cleaned,
            "blocks": [{"text": cleaned, "source": source_name}],
            "blocks_data": {"block_1": {"text": cleaned, "source": source_name}},
        }

    @staticmethod
    def _clean_ocr_text(text):
        if not text:
            return ""
        filtered = re.sub(r"\r+", "\n", text)
        filtered = filtered.replace("\xa0", " ")
        filtered = re.sub(r"\n{3,}", "\n\n", filtered)
        return filtered.strip()


class TextLayerPdfProcessor(BasePdfProcessor):
    """Text-layer extractor для .cdw/.cwd PDF, перенесённый из эксперимента."""

    ITEM_RE = re.compile(r"^\s*(\d{1,2})[\).]?\s+(.+)$")
    DASH_RE = re.compile(r"^\s*[-–—]\s+(.+)$")
    STRONG_WORDS = [
        "ГОСТ", "ОСТ", "ТУ", "РД",
        "МАТЕРИАЛ", "МАТЕРИАЛ-ЗАМЕНИТЕЛЬ",
        "МАРКИРОВАТЬ", "МАРКИРОВКА",
        "ПОКРЫТИЕ", "ПОКРЫТЬ",
        "ДОПУСК", "ДОПУСКИ", "ОБЩИЕ ДОПУСКИ",
        "НЕУКАЗАННЫЕ", "ОТКЛОНЕНИЯ",
        "РАЗМЕР", "РАЗМЕРЫ",
        "РАДИУС", "РАДИУСЫ",
        "ОБЕСПЕЧ", "ИНСТР",
        "КОНТРОЛЬ", "СВАРК", "ИСПЫТАН",
        "БИРКЕ", "КТ",
    ]
    SIGNATURE_WORDS = [
        "ДОКУМЕНТ ПОДПИСАН",
        "СЕРТИФИКАТ",
        "ВЛАДЕЛЕЦ ПОДПИСИ",
        "ДЕЙСТВИТЕЛЬНО С",
        "ЭЦП",
    ]
    TITLE_WORDS = [
        "ИЗМ.", "ЛИСТ", "№ ДОКУМ", "ПОДП.", "ДАТА",
        "РАЗРАБ.", "ПРОВ.", "Т.КОНТР.", "Н.КОНТР.",
        "УТВ.", "МАССА", "МАСШТАБ", "ФОРМАТ",
        "КОПИРОВАЛ", "CRC", "ID ВЕРСИИ",
    ]

    @classmethod
    def supports(cls, file_name):
        name = str(file_name or "").lower()
        return (
            ".cdw.pdf" in name or name.endswith(".cdw.pdf") or
            ".cwd.pdf" in name or name.endswith(".cwd.pdf") or
            ".cdw" in name or ".cwd" in name
        )

    @staticmethod
    def _normalize_text(value):
        return re.sub(r"\s+", " ", str(value).replace("\xa0", " ")).strip()

    @staticmethod
    def _normalize_block_text(value):
        text = str(value or "").replace("\r", "\n")
        text = re.sub(r"\n{3,}", "\n\n", text)
        return re.sub(r"\n\s*\n", "\n", text).strip()

    @classmethod
    def _upper(cls, text):
        return cls._normalize_text(text).upper().replace("Ё", "Е")

    @classmethod
    def _has_strong_word(cls, text):
        u = cls._upper(text)
        return any(word in u for word in cls.STRONG_WORDS)

    @classmethod
    def _is_signature(cls, text):
        u = cls._upper(text)
        return any(word in u for word in cls.SIGNATURE_WORDS)

    @classmethod
    def _is_title_block(cls, text):
        u = cls._upper(text)
        return any(word in u for word in cls.TITLE_WORDS)

    @classmethod
    def _is_short_dimension_item(cls, text):
        t = cls._normalize_text(text)
        if not t:
            return False
        m = cls.ITEM_RE.match(t)
        if not m:
            return False
        rest = cls._upper(m.group(2)).strip()
        rest_len = len(rest)
        if re.search(r"ВНУТРЕН|СКРУГЛЕН|НЕ\s+БОЛЕЕ|НЕУКАЗАН|ДОПУСК|МАРКИРОВАТЬ|МАТЕРИАЛ|ПОКРЫТИЕ|ГОСТ|ОСТ|ТУ", rest):
            return False
        if re.match(r"^ОТВЕРСТИ[ЕЯ]", rest):
            return False
        if re.match(r"^(ОТВ\.?|ФАСК[А-Я]*|РАДИУС[А-Я]*|R[0-9]|RA\s|Ø|Ç|M[0-9])(\s|\.|$)", rest):
            if rest_len <= 65:
                return True
        if re.match(r"^[0-9]+\s*(ОТВ\.?|ФАСК[А-Я]*|РАДИУС[А-Я]*)", rest):
            if rest_len <= 65:
                return True
        return False

    @classmethod
    def _item_number(cls, text):
        m = cls.ITEM_RE.match(cls._normalize_text(text))
        if not m:
            return None
        try:
            return int(m.group(1))
        except ValueError:
            return None

    @classmethod
    def _classify_line(cls, text):
        t = cls._normalize_text(text)
        if not t:
            return "empty"
        if cls._is_signature(t):
            return "signature"
        if cls._is_title_block(t):
            return "title"
        if cls._is_short_dimension_item(t):
            return "bad_dim"
        if cls.ITEM_RE.match(t):
            m = cls.ITEM_RE.match(t)
            rest = m.group(2)
            if cls._has_strong_word(t) or len(rest) >= 18:
                return "item"
        if cls.DASH_RE.match(t):
            return "dash"
        return "continuation"

    @classmethod
    def _trim_words_to_embedded_requirement(cls, ws):
        if not ws:
            return ws
        for idx in range(len(ws)):
            token = cls._normalize_text(ws[idx][4])
            token_clean = token.strip().replace(".", "").replace(")", "")
            if not re.match(r"^\d{1,2}\*?$", token_clean):
                continue
            rest_text = cls._normalize_text(" ".join(str(w[4]) for w in ws[idx:]))
            if cls._is_short_dimension_item(rest_text):
                continue
            if cls._has_strong_word(rest_text) or len(rest_text) >= 28:
                return ws[idx:]
        return ws

    @staticmethod
    def _bbox_union(items):
        if not items:
            return [0, 0, 0, 0]
        return [
            min(item["bbox"][0] for item in items),
            min(item["bbox"][1] for item in items),
            max(item["bbox"][2] for item in items),
            max(item["bbox"][3] for item in items),
        ]

    @staticmethod
    def _rect_iou(a, b):
        ax1, ay1, ax2, ay2 = a
        bx1, by1, bx2, by2 = b
        ix1 = max(ax1, bx1)
        iy1 = max(ay1, by1)
        ix2 = min(ax2, bx2)
        iy2 = min(ay2, by2)
        if ix2 <= ix1 or iy2 <= iy1:
            return 0.0
        inter = (ix2 - ix1) * (iy2 - iy1)
        area_a = max(1.0, (ax2 - ax1) * (ay2 - ay1))
        area_b = max(1.0, (bx2 - bx1) * (by2 - by1))
        return inter / (area_a + area_b - inter)

    @staticmethod
    def _overlap_x(a, b):
        ax1, _, ax2, _ = a
        bx1, _, bx2, _ = b
        inter = max(0.0, min(ax2, bx2) - max(ax1, bx1))
        return inter / max(1.0, min(ax2 - ax1, bx2 - bx1))

    @staticmethod
    def _median_line_height(lines):
        heights = [line["bbox"][3] - line["bbox"][1] for line in lines if line["bbox"][3] > line["bbox"][1]]
        if not heights:
            return 8.0
        return median(heights)

    @staticmethod
    def _same_requirement_zone(line, block_bbox, base_x, page_w):
        b = line["bbox"]
        if abs(line["x1"] - base_x) <= 35:
            return True
        if base_x <= line["x1"] <= base_x + page_w * 0.22:
            return True
        if TextLayerPdfProcessor._overlap_x(b, block_bbox) >= 0.25:
            return True
        return False

    def _extract_lines(self, page):
        words = page.get_text("words", sort=True)
        groups = {}

        for w in words:
            if len(w) < 8:
                continue
            _, _, _, _, text, block_no, line_no, _ = w[:8]
            text = self._normalize_text(text)
            if not text:
                continue
            key = (int(block_no), int(line_no))
            groups.setdefault(key, []).append(w)

        lines = []
        for ws in groups.values():
            ws = sorted(ws, key=lambda z: z[0])
            ws = self._trim_words_to_embedded_requirement(ws)
            text = self._normalize_text(" ".join(str(w[4]) for w in ws))
            if not text:
                continue
            bbox = [
                min(w[0] for w in ws),
                min(w[1] for w in ws),
                max(w[2] for w in ws),
                max(w[3] for w in ws),
            ]
            lines.append({
                "text": text,
                "bbox": bbox,
                "x1": bbox[0],
                "y1": bbox[1],
                "x2": bbox[2],
                "y2": bbox[3],
                "kind": self._classify_line(text),
                "item_number": self._item_number(text),
            })

        lines.sort(key=lambda line: (line["y1"], line["x1"]))
        return lines

    def _build_candidate_from_anchor(self, lines, anchor_index, page_w, page_h):
        anchor = lines[anchor_index]
        if anchor["kind"] != "item":
            return None

        base_x = anchor["x1"]
        collected = [anchor]
        block_bbox = anchor["bbox"][:]
        med_h = self._median_line_height(lines)
        last_y2 = anchor["y2"]

        for j in range(anchor_index + 1, len(lines)):
            line = lines[j]
            if line["y1"] < anchor["y1"] - 1:
                continue
            gap = line["y1"] - last_y2
            if gap > max(18.0, med_h * 3.2):
                if line["kind"] != "item" or not self._same_requirement_zone(line, block_bbox, base_x, page_w):
                    break
            if line["kind"] in ("signature", "title"):
                if len(collected) >= 1:
                    break
                continue
            if line["kind"] == "bad_dim":
                continue
            if line["kind"] == "item":
                if not self._same_requirement_zone(line, block_bbox, base_x, page_w):
                    continue
                collected.append(line)
                block_bbox = self._bbox_union(collected)
                last_y2 = max(last_y2, line["y2"])
                continue
            if line["kind"] in ("dash", "continuation"):
                if self._same_requirement_zone(line, block_bbox, base_x, page_w):
                    if line["kind"] == "dash" or len(line["text"]) >= 5:
                        collected.append(line)
                        block_bbox = self._bbox_union(collected)
                        last_y2 = max(last_y2, line["y2"])
                continue

        if not collected:
            return None

        text = "\n".join(line["text"] for line in collected)
        nums = [line["item_number"] for line in collected if line.get("item_number") is not None]
        return {
            "lines": collected,
            "bbox": self._bbox_union(collected),
            "text": text,
            "item_numbers": nums,
            "line_count": len(collected),
        }

    def _score_candidate(self, candidate, page_w, page_h):
        text = candidate["text"]
        u = self._upper(text)
        bbox = candidate["bbox"]
        item_count = len(candidate["item_numbers"])
        dash_count = sum(1 for line in candidate["lines"] if line["kind"] == "dash")
        cont_count = sum(1 for line in candidate["lines"] if line["kind"] == "continuation")
        strong_count = sum(1 for word in self.STRONG_WORDS if word in u)

        bw = bbox[2] - bbox[0]
        bh = bbox[3] - bbox[1]
        area_rel = (bw * bh) / max(1.0, page_w * page_h)

        score = 0.0
        reasons = []
        if item_count >= 1:
            score += 30
            reasons.append("+items")
        if item_count >= 2:
            score += 35
            reasons.append("+multi_items")
        if dash_count > 0:
            score += 12
            reasons.append("+dash_subitems")
        if cont_count > 0:
            score += 8
            reasons.append("+continuations")
        if strong_count:
            score += min(50, strong_count * 8)
            reasons.append("+keywords")

        nums = candidate["item_numbers"]
        if nums:
            uniq = []
            for n in nums:
                if n not in uniq:
                    uniq.append(n)
            if len(uniq) >= 2:
                seq_bonus = 0
                for a, b in zip(uniq, uniq[1:]):
                    if b == a + 1:
                        seq_bonus += 8
                if seq_bonus:
                    score += seq_bonus
                    reasons.append("+sequence")
            if 1 in uniq:
                score += 8
                reasons.append("+has_1")

        if area_rel > 0.20:
            score -= 60
            reasons.append("-huge")
        if bw > page_w * 0.75:
            score -= 45
            reasons.append("-too_wide")
        if bh > page_h * 0.45:
            score -= 35
            reasons.append("-too_tall")
        if item_count == 1 and len(text) < 45 and dash_count == 0:
            score -= 45
            reasons.append("-short_single")
        if any(self._is_signature(line["text"]) or self._is_title_block(line["text"]) for line in candidate["lines"]):
            score -= 100
            reasons.append("-signature_or_title")

        candidate["score"] = round(score, 2)
        candidate["reasons"] = reasons
        candidate["features"] = {
            "item_count": item_count,
            "dash_count": dash_count,
            "continuation_count": cont_count,
            "strong_word_count": strong_count,
            "area_rel": round(area_rel, 5),
        }
        return candidate

    def _make_candidates(self, lines, page_w, page_h):
        candidates = []
        for i, line in enumerate(lines):
            if line["kind"] != "item":
                continue
            candidate = self._build_candidate_from_anchor(lines, i, page_w, page_h)
            if not candidate:
                continue
            candidate = self._score_candidate(candidate, page_w, page_h)
            if candidate["score"] < 15:
                continue
            candidates.append(candidate)

        candidates.sort(key=lambda c: c["score"], reverse=True)
        unique = []
        for c in candidates:
            duplicate = False
            for old in unique:
                if self._rect_iou(c["bbox"], old["bbox"]) > 0.55:
                    duplicate = True
                    break
                cx1, cy1, cx2, cy2 = c["bbox"]
                ox1, oy1, ox2, oy2 = old["bbox"]
                inside = (
                    cx1 >= ox1 - 5 and cy1 >= oy1 - 5 and
                    cx2 <= ox2 + 5 and cy2 <= oy2 + 5
                )
                if inside:
                    duplicate = True
                    break
            if not duplicate:
                unique.append(c)
        return unique

    @staticmethod
    def _select_blocks(candidates, max_blocks=3):
        selected = []
        for candidate in sorted(candidates, key=lambda c: c["score"], reverse=True):
            if candidate["score"] < 35:
                continue
            bb = candidate["bbox"]
            overlap = False
            for old in selected:
                if TextLayerPdfProcessor._rect_iou(bb, old["bbox"]) > 0.25:
                    overlap = True
                    break
            if overlap:
                continue
            selected.append(candidate)
            if len(selected) >= max_blocks:
                break
        return selected

    def process(self, pdf_bytes, source_name=""):
        if fitz is None:
            raise RuntimeError("PyMuPDF (fitz) не установлен. Невозможно использовать текстовый слой.")

        logger.info(f"TextLayerPdfProcessor: обработка файла {source_name or 'без имени'}")
        doc = fitz.open(stream=pdf_bytes, filetype="pdf")
        try:
            block_texts = []
            block_data = {}
            seen = set()

            for page_index, page in enumerate(doc):
                if page_index > 0:
                    continue
                lines = self._extract_lines(page)
                candidates = self._make_candidates(lines, float(page.rect.width), float(page.rect.height))
                selected = self._select_blocks(candidates, max_blocks=3)

                for idx, candidate in enumerate(selected, start=1):
                    text = self._normalize_block_text(candidate["text"])
                    if not text:
                        continue
                    key = text.lower().strip()
                    if key in seen:
                        continue
                    seen.add(key)
                    block_texts.append(text)
                    block_data[f"block_{idx}"] = {
                        "bbox": candidate["bbox"],
                        "score": candidate.get("score", 0),
                        "text": text,
                    }
                    self._store_block_text(text, source_name)

            full_text = "\n\n".join(block_texts)
            return {
                "text": full_text,
                "blocks": block_texts,
                "blocks_data": block_data,
            }
        finally:
            doc.close()


class PdfProcessingFactory:
    """Фабрика процессоров для выбора реализации по имени файла."""

    @staticmethod
    def create(file_name, token_storage=None):
        normalized = str(file_name or "").lower()

        if OCRPdfProcessor.supports(normalized):
            return OCRPdfProcessor(token_storage=token_storage)
        if TextLayerPdfProcessor.supports(normalized):
            return TextLayerPdfProcessor(token_storage=token_storage)

        if fitz is not None:
            return TextLayerPdfProcessor(token_storage=token_storage)
        return OCRPdfProcessor(token_storage=token_storage)


__all__ = [
    "BasePdfProcessor",
    "OCRPdfProcessor",
    "TextLayerPdfProcessor",
    "PdfProcessingFactory",
    "TokenStorage",
]
