                continue
            if any(token in upper for token in ("ДОКУМЕНТ ПОДПИСАН", "СЕРТИФИКАТ", "ЭЦП", "ЛИСТ", "ФОРМАТ", "ВЕРСИИ", "КОПИРОВАЛ")):
